import type { ButtonProps } from "./button.types";

import { forwardRef, useCallback, useEffect, useRef, useState } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { useFormSize } from "@components/form/hooks/use-form-size";
import { CircleProgress } from "@components/circle-progress";

import { ButtonClasses, StyledButton } from "./button.styles";

const Button = forwardRef(
  (
    {
      className,
      variant = "default",
      buttonType = "primary",
      size: sizeProp,
      children,
      disabled = false,
      selected: controlledSelected,
      toggle = false,
      onValueChange,
      onClick,
      value,
      isLoading = false,
      ...props
    }: ButtonProps,
    ref: React.ForwardedRef<HTMLButtonElement>,
  ) => {
    const theme = useTheme();
    const formContext = useFormSize();
    const size = sizeProp || formContext?.formSize;

    const [internalSelected, setInternalSelected] = useState(false);
    const isControlled = controlledSelected !== undefined;
    const isSelected = isControlled ? controlledSelected : internalSelected;

    const hasMounted = useRef(false);
    useEffect(() => {
      if (!hasMounted.current) {
        hasMounted.current = true;
        return;
      }
      onValueChange?.(Boolean(controlledSelected));
    }, [isControlled, controlledSelected, onValueChange]);

    const handleClick = useCallback(
      (e: React.MouseEvent<HTMLButtonElement>) => {
        if (isLoading || disabled) return;

        if (toggle) {
          if (!isControlled) {
            setInternalSelected(!internalSelected);
          }
          onValueChange?.(!isSelected);
        }
        onClick?.(e);
      },
      [
        toggle,
        isControlled,
        onValueChange,
        isSelected,
        onClick,
        internalSelected,
        isLoading,
        disabled,
      ],
    );

    const rootClasses = clsx(ButtonClasses.root, className, {
      [ButtonClasses.secondary]: buttonType === "secondary",
      [ButtonClasses.tertiary]: buttonType === "tertiary",
      [ButtonClasses.sm]: size === "sm",
      [ButtonClasses.loading]: isLoading,
    });

    return (
      <StyledButton
        ref={ref}
        aria-busy={isLoading}
        aria-disabled={disabled || isLoading}
        aria-pressed={toggle ? isSelected : undefined}
        className={rootClasses}
        currentTheme={theme}
        data-selected={isSelected ? "true" : undefined}
        disabled={disabled}
        type="button"
        value={value}
        variant={variant}
        onClick={handleClick}
        {...props}
      >
        <span className={ButtonClasses.content}>{children}</span>
        {isLoading && (
          <span className={ButtonClasses.loadingWrapper}>
            <CircleProgress variant="inherit" />
          </span>
        )}
      </StyledButton>
    );
  },
);

Button.displayName = "Button";

export default Button;
